using System;using System.Collections.Generic;using System.Data.SqlClient;using AshkanPharmacy.Models;
namespace AshkanPharmacy.Core { public static class PatientRepository {
 public static List<PatientProfile> Search(string term){var a=new List<PatientProfile>();if(!Database.IsAvailable)return a;using(var c=Database.Open())using(var q=new SqlCommand("SELECT TOP 100 Id,FullName,NationalCode,Phone,Insurance,InsuranceNo,Allergies,ChronicConditions,Notes FROM dbo.PatientProfiles WHERE @q='' OR FullName LIKE @like OR NationalCode LIKE @like ORDER BY FullName",c)){q.Parameters.AddWithValue("@q",term??"");q.Parameters.AddWithValue("@like","%"+(term??"")+"%");using(var r=q.ExecuteReader())while(r.Read())a.Add(new PatientProfile{Id=r.GetInt32(0),FullName=r.IsDBNull(1)?"":r.GetString(1),NationalCode=r.IsDBNull(2)?"":r.GetString(2),Phone=r.IsDBNull(3)?"":r.GetString(3),Insurance=r.IsDBNull(4)?"":r.GetString(4),InsuranceNo=r.IsDBNull(5)?"":r.GetString(5),Allergies=r.IsDBNull(6)?"":r.GetString(6),ChronicConditions=r.IsDBNull(7)?"":r.GetString(7),Notes=r.IsDBNull(8)?"":r.GetString(8)});}return a;}
 } }